.darma-loader-darma-b17-tic-tac-toe { --accent: var(--loader-color, #334155); --accent-2: var(--loader-secondary-color, #f43f5e); width: var(--loader-size, 116px); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b17-tic-tac-toe .darma-loader-darma-b17-tic-tac-toe__rule { position: absolute; background: color-mix(in srgb, var(--accent) 55%, transparent); border-radius: 3px; }
.darma-loader-darma-b17-tic-tac-toe .darma-loader-darma-b17-tic-tac-toe__rule:nth-of-type(1) { left: 32%; top: 4%; width: 3%; height: 92%; }
.darma-loader-darma-b17-tic-tac-toe .darma-loader-darma-b17-tic-tac-toe__rule:nth-of-type(2) { left: 65%; top: 4%; width: 3%; height: 92%; }
.darma-loader-darma-b17-tic-tac-toe .darma-loader-darma-b17-tic-tac-toe__rule:nth-of-type(3) { top: 32%; left: 4%; height: 3%; width: 92%; }
.darma-loader-darma-b17-tic-tac-toe .darma-loader-darma-b17-tic-tac-toe__rule:nth-of-type(4) { top: 65%; left: 4%; height: 3%; width: 92%; }
.darma-loader-darma-b17-tic-tac-toe span { position: absolute; width: 20%; height: 20%; border-radius: 50%; box-shadow: inset 0 0 0 4px var(--accent); transform: scale(0); animation: darma-loader-darma-b17-tic-tac-toe-ttt-mark calc(var(--loader-speed, 1s) * 3.6) ease-out infinite; }
.darma-loader-darma-b17-tic-tac-toe span:nth-of-type(1) { left: 7%; top: 7%; border-radius: 3px; box-shadow: none; background: linear-gradient(45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%), linear-gradient(-45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%); }
.darma-loader-darma-b17-tic-tac-toe span:nth-of-type(2) { left: 40%; top: 40%; animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b17-tic-tac-toe span:nth-of-type(3) { left: 73%; top: 7%; border-radius: 3px; box-shadow: none; background: linear-gradient(45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%), linear-gradient(-45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%); animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b17-tic-tac-toe span:nth-of-type(4) { left: 7%; top: 73%; animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b17-tic-tac-toe span:nth-of-type(5) { left: 40%; top: 7%; border-radius: 3px; box-shadow: none; background: linear-gradient(45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%), linear-gradient(-45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%); animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
.darma-loader-darma-b17-tic-tac-toe .darma-loader-darma-b17-tic-tac-toe__win { position: absolute; left: 10%; top: 15%; width: 80%; height: 4%; border-radius: 3px; background: var(--accent-2); transform-origin: 0 50%; transform: scaleX(0); animation: darma-loader-darma-b17-tic-tac-toe-ttt-win calc(var(--loader-speed, 1s) * 3.6) ease-out infinite; }
@keyframes darma-loader-darma-b17-tic-tac-toe-ttt-mark { 0%, 6% { transform: scale(0); opacity: 0; } 16%, 76% { transform: scale(1); opacity: 1; } 88%, 100% { transform: scale(0); opacity: 0; } }
@keyframes darma-loader-darma-b17-tic-tac-toe-ttt-win { 0%, 52% { transform: scaleX(0); opacity: 0; } 62%, 78% { transform: scaleX(1); opacity: 1; } 88%, 100% { transform: scaleX(0); opacity: 0; } }

